/*
 * Reviewer B: what is inside each built chunk.
 * Needs an analysis build WITH source maps, written outside the repo:
 *   cd app && npx vite build --outDir /tmp/dist-map --sourcemap --emptyOutDir
 *   node ../docs/reviews/evidence/bundle-attribution.cjs /tmp/dist-map/assets
 * (run from app/ so that source-map-js resolves from app/node_modules)
 * Attributes every generated byte of the minified file to its original source.
 */
const fs = require('fs');
const path = require('path');
const { SourceMapConsumer } = require(require.resolve('source-map-js', { paths: [process.cwd()] }));

const dir = process.argv[2];
const bucket = (source) => {
  if (!source) return '(unmapped: wrappers, helpers)';
  const s = source.replace(/\\/g, '/');
  let m;
  if ((m = /node_modules\/((?:@[^/]+\/)?[^/]+)/.exec(s))) {
    if (m[1] === 'core-js') return 'core-js';
    return 'npm:' + m[1];
  }
  if ((m = /src\/shared\/([^/]+)/.exec(s))) return 'src/shared/' + m[1] + (s.endsWith('.css') ? ' (css)' : '');
  if ((m = /src\/(app|features)\/([^/]+)/.exec(s))) return 'src/' + m[1] + '/' + m[2];
  if (/mock\//.test(s)) return 'MOCK ' + s;
  return s.replace(/^.*\/app\//, '');
};

for (const file of fs.readdirSync(dir).filter((f) => f.endsWith('.js')).sort()) {
  if (!fs.existsSync(path.join(dir, file + '.map'))) { console.log('\n' + file + '  (no source map emitted)'); continue; }
  const code = fs.readFileSync(path.join(dir, file), 'utf8');
  const map = new SourceMapConsumer(JSON.parse(fs.readFileSync(path.join(dir, file + '.map'), 'utf8')));
  const lines = code.split('\n');
  const starts = [];
  let offset = 0;
  for (const line of lines) {
    starts.push(offset);
    offset += line.length + 1;
  }
  const mappings = [];
  map.eachMapping((m) => mappings.push({ pos: starts[m.generatedLine - 1] + m.generatedColumn, source: m.source }));
  mappings.sort((a, b) => a.pos - b.pos);
  const totals = new Map();
  for (let i = 0; i < mappings.length; i += 1) {
    const end = i + 1 < mappings.length ? mappings[i + 1].pos : code.length;
    const key = bucket(mappings[i].source);
    totals.set(key, (totals.get(key) || 0) + (end - mappings[i].pos));
  }
  const mapped = [...totals.values()].reduce((a, b) => a + b, 0);
  totals.set('(unmapped: wrappers, helpers)', (totals.get('(unmapped: wrappers, helpers)') || 0) + code.length - mapped);
  console.log('\n' + file + '  ' + (code.length / 1024).toFixed(1) + ' KB raw');
  for (const [key, bytes] of [...totals.entries()].sort((a, b) => b[1] - a[1])) {
    if (bytes < 200) continue;
    console.log('  ' + (bytes / 1024).toFixed(1).padStart(7) + ' KB  ' + ((bytes / code.length) * 100).toFixed(1).padStart(5) + '%  ' + key);
  }
  const sources = map.sources.filter((s) => /mock\/|dev\/|KitchenSink|\.test\./.test(s));
  console.log('  dev/mock/test sources in this chunk: ' + (sources.length ? sources.join(', ') : 'none'));
}
